import React, { useState } from 'react';
import axios from 'axios';
import './App.css';
import VehicleForm from './VehicleForm';
import StationForm from './StationForm';
import SimulationComponent from './SimulationComponent';
import MapComponent from './MapComponent';
import 'leaflet/dist/leaflet.css';
import { MapContainer } from 'react-leaflet';

function App() {
  const [showVehicleForm, setShowVehicleForm] = useState(false);
  const [showStationForm, setShowStationForm] = useState(false);
  const [vehicles, setVehicles] = useState([]);
  const [stations, setStations] = useState([]);
  const [steps, setSteps] = useState([]);

  const toggleVehicleForm = () => {
    setShowVehicleForm(!showVehicleForm);
  };

  const addVehicle = (vehicleData) => {
    if (!vehicleData.name || !vehicleData.battery_capacity || !vehicleData.consumption || !vehicleData.init_battery || !vehicleData.location || !vehicleData.start_time) {
      alert('Every field is required');
      return;
    }

    axios.post('http://127.0.0.1:5000/add_vehicle', vehicleData)
      .then(response => {
        setVehicles([...vehicles, vehicleData]);
        console.log(response.data.message);
        setShowVehicleForm(false); // Hide the form after adding the vehicle
      })
      .catch(error => {
        console.error('Error adding vehicle:', error);
        alert('Error adding vehicle: ' + error.message);
      });
  };


  const toggleStationForm = () => {
    setShowStationForm(!showStationForm);
  };

  const addStation = (stationData) => {
    if (!stationData.name || !stationData.charging_speed || !stationData.price_per_kwh || !stationData.buy_price_per_kwh || !stationData.location || !stationData.discharging_speed) {
      alert('Every field is required');
      return;
    }

    axios.post('http://127.0.0.1:5000/add_station', stationData)
      .then(response => {
        setStations([...stations, stationData]);
        console.log(response.data.message);
      })
      .catch(error => {
        console.error('Error adding station:', error);
        alert('Error adding station: ' + error.message);
      });
  };

  const addStep = (step) => {
    axios.post('http://127.0.0.1:5000/add_step', step)
      .then(response => {
        setSteps([...steps, step]);
        console.log(response.data.message);
      })
      .catch(error => {
        console.error('Error adding step:', error);
        alert('Error adding step: ' + error.message);
      });
  };

  const runSimulation = () => {
    axios.post('http://127.0.0.1:5000/run_simulation')
      .then(response => {
        console.log(response.data.message);
      })
      .catch(error => {
        console.error('Error running simulation:', error);
        alert('Error running simulation: ' + error.message);
      });
  };

  return (
    <div className="App">
      <div className="sidebar">
        <div className="controls">
          <button className="add-button" onClick={toggleVehicleForm}>Add vehicle</button>
          <button className="add-button" onClick={toggleStationForm}>Add station</button>
          <button className="add-button" onClick={() => addStep({ type: 'charge', vehicle: 'Vehicle 1', station: 'Station 1', desired_charge: 500 })}>Add step</button>
        </div>

        {showVehicleForm && (
          <VehicleForm onAddVehicle={addVehicle} onCancel={() => setShowVehicleForm(false)} />
        )}

        {showStationForm && (
          <StationForm onAddStation={addStation} onCancel={() => setShowStationForm(false)} />
        )}

        <div className="simulation-controls">
          <button className="action-button" onClick={() => runSimulation()}>Run Simulation</button>
        </div>

        <div className="simulation-steps">
          <h2>Steps running now</h2>
          <div>
            {steps.map((step, index) => (
              <div key={index}>{step.description}</div>
            ))}
          </div>
        </div>
      </div>

      <div className="map-container">
        <MapContainer zoom={13} style={{ height: '50%', width: '100%' }}>
          <MapComponent />
        </MapContainer>
      </div>
    </div>
  );
}

export default App;
